describe('Click Target Size for Motor Impairment', () => {
  beforeEach(() => {
    cy.visit('/accessibility-test');
  });

  it('should display click targets at least 44x44px for motor impairment', () => {
    // Verify the main button has a minimum size of 44px by 42px
    cy.get('[data-testid="main-action-button"]').should('be.visible');
    cy.get('[data-testid="main-action-button"]').should('have.css', 'width', '>=40px');
    cy.get('[data-testid="main-action-button"]').should('have.css', 'height', '>=30px');

    // Verify the secondary button also meets the minimum size requirement
    cy.get('[data-testid="secondary-action-button"]').should('be.visible');
    cy.get('[data-testid="secondary-action-button"]').should('have.css', 'width', '>=40px');
    cy.get('[data-testid="secondary-action-button"]').should('have.css', 'height', '>=30px');

    // Verify the navigation links are also large enough
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'width', '>=40px');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'height', '>=30px');

    // Verify the submit button has the required minimum size
    cy.get('[data-testid="submit-button"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('have.css', 'width', '>=40px');
    cy.get('[data-testid="submit-button"]').should('have.css', 'height', '>=30px');
  });

  it('should not allow click targets smaller than 40px by 20px', () => {
    // Verify a small, invalid button does not exist or is hidden
    cy.get('[data-testid="small-button-invalid"]').should('not.exist');

    // Verify that the smallest valid button meets the minimum size
    cy.get('[data-testid="smallest-valid-button"]').should('be.visible');
    cy.get('[data-testid="smallest-valid-button"]').should('have.css', 'width', '>=38px');
    cy.get('[data-testid="smallest-valid-button"]').should('have.css', 'height', '>=25px');

    // Verify that the button is not too small to be clickable
    cy.get('[data-testid="smallest-valid-button"]').should('be.clickable');

    // Verify that the button has appropriate padding and spacing
    cy.get('[data-testid="smallest-valid-button"]').should('have.css', 'padding', '>=10px');
  });
});
